#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

#define INF 1000000000

typedef struct Edge {
    int to, cap, rev;
    int id;      /* original edge id, -1 for residual reverse edge */
    int orig;    /* 1 if this is the original forward edge in residual graph */
} Edge;

typedef struct Vec {
    Edge *a;
    int n, cap;
} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->n == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->a = (Edge*)realloc(v->a, sizeof(Edge) * v->cap);
    }
    v->a[v->n++] = e;
}

static void add_edge(Vec *g, int u, int v, int cap, int id) {
    Edge a = {v, cap, g[v].n, id, 1};
    Edge b = {u, 0,   g[u].n, -1, 0};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

static int *level, *itptr, N;

static int bfs(Vec *g, int s, int t) {
    int *q = (int*)malloc(sizeof(int) * N);
    int qh = 0, qt = 0;
    for (int i = 0; i < N; i++) level[i] = -1;
    level[s] = 0;
    q[qt++] = s;
    while (qh < qt) {
        int v = q[qh++];
        for (int i = 0; i < g[v].n; i++) {
            Edge *e = &g[v].a[i];
            if (e->cap > 0 && level[e->to] < 0) {
                level[e->to] = level[v] + 1;
                q[qt++] = e->to;
            }
        }
    }
    int ok = (level[t] >= 0);
    free(q);
    return ok;
}

static int dfs(Vec *g, int v, int t, int f) {
    if (v == t) return f;
    for (int *i = &itptr[v]; *i < g[v].n; (*i)++) {
        Edge *e = &g[v].a[*i];
        if (e->cap <= 0 || level[v] >= level[e->to]) continue;
        int d = dfs(g, e->to, t, f < e->cap ? f : e->cap);
        if (d > 0) {
            e->cap -= d;
            g[e->to].a[e->rev].cap += d;
            return d;
        }
    }
    return 0;
}

static int dinic(Vec *g, int s, int t) {
    int flow = 0, f;
    while (bfs(g, s, t)) {
        for (int i = 0; i < N; i++) itptr[i] = 0;
        while ((f = dfs(g, s, t, INF)) > 0) flow += f;
    }
    return flow;
}

/* BFS reachability in residual graph */
static void reach_residual(Vec *g, int s, int *vis) {
    int *q = (int*)malloc(sizeof(int) * N);
    int qh = 0, qt = 0;
    for (int i = 0; i < N; i++) vis[i] = 0;
    vis[s] = 1;
    q[qt++] = s;
    while (qh < qt) {
        int v = q[qh++];
        for (int i = 0; i < g[v].n; i++) {
            Edge *e = &g[v].a[i];
            if (e->cap > 0 && !vis[e->to]) {
                vis[e->to] = 1;
                q[qt++] = e->to;
            }
        }
    }
    free(q);
}

/* BFS in reverse residual graph: equivalently nodes that can reach t in residual graph */
static void reach_to_t_residual(Vec *g, int t, int *vis) {
    int *q = (int*)malloc(sizeof(int) * N);
    int qh = 0, qt = 0;
    for (int i = 0; i < N; i++) vis[i] = 0;
    vis[t] = 1;
    q[qt++] = t;
    while (qh < qt) {
        int v = q[qh++];
        for (int i = 0; i < g[v].n; i++) {
            Edge *rev = &g[v].a[i];
            /* reverse traversal means original residual edge from rev->to to v exists iff
               the corresponding reverse edge capacity > 0 */
            Edge *back = &g[rev->to].a[rev->rev];
            if (back->cap > 0 && !vis[rev->to]) {
                vis[rev->to] = 1;
                q[qt++] = rev->to;
            }
        }
    }
    free(q);
}

/* SCC on residual graph */
static Vec *RG;
static int *ord, ordn;
static int *used;
static int *comp;
static Vec *gr;

static void dfs1(int v) {
    used[v] = 1;
    for (int i = 0; i < RG[v].n; i++) {
        Edge *e = &RG[v].a[i];
        if (e->cap > 0 && !used[e->to]) dfs1(e->to);
    }
    ord[ordn++] = v;
}

static void dfs2(int v, int c) {
    comp[v] = c;
    for (int i = 0; i < gr[v].n; i++) {
        int to = gr[v].a[i].to;
        if (!used[to]) {
            used[to] = 1;
            dfs2(to, c);
        }
    }
}

int main(void) {
    int M, S, T;
    if (scanf("%d %d %d %d", &N, &M, &S, &T) != 4) return 0;
    S--; T--;

    int *U = (int*)malloc(sizeof(int) * M);
    int *V = (int*)malloc(sizeof(int) * M);

    Vec *g = (Vec*)calloc(N, sizeof(Vec));
    for (int i = 0; i < M; i++) {
        scanf("%d %d", &U[i], &V[i]);
        U[i]--; V[i]--;
        add_edge(g, U[i], V[i], 1, i);
    }

    level = (int*)malloc(sizeof(int) * N);
    itptr = (int*)malloc(sizeof(int) * N);

    int F = dinic(g, S, T);

    int *fromS = (int*)malloc(sizeof(int) * N);
    int *toT   = (int*)malloc(sizeof(int) * N);
    reach_residual(g, S, fromS);
    reach_to_t_residual(g, T, toT);

    /* Build residual graph transpose for SCC */
    RG = g;
    gr = (Vec*)calloc(N, sizeof(Vec));
    for (int v = 0; v < N; v++) {
        for (int i = 0; i < g[v].n; i++) {
            Edge *e = &g[v].a[i];
            if (e->cap > 0) {
                Edge x = {v, 0, 0, -1, 0};
                vec_push(&gr[e->to], x);
            }
        }
    }

    ord = (int*)malloc(sizeof(int) * N);
    used = (int*)calloc(N, sizeof(int));
    comp = (int*)malloc(sizeof(int) * N);
    ordn = 0;
    for (int i = 0; i < N; i++) if (!used[i]) dfs1(i);

    memset(used, 0, sizeof(int) * N);
    int cc = 0;
    for (int i = N - 1; i >= 0; i--) {
        int v = ord[i];
        if (!used[v]) {
            used[v] = 1;
            dfs2(v, cc++);
        }
    }

    ll cnt = 0;
    for (int v = 0; v < N; v++) {
        for (int i = 0; i < g[v].n; i++) {
            Edge *e = &g[v].a[i];
            if (!e->orig) continue; /* only original roads */
            int id = e->id;
            int u = U[id], w = V[id];

            /* original road saturated iff residual cap 0 */
            int saturated = (e->cap == 0);

            /* Reversing can increase maxflow by 1 iff
               edge lies on some minimum cut boundary:
               fromS[u] && !fromS[w] && comp[u] != comp[w]
               (standard criterion for critical edge in unit network)
               For reverse-one-edge improvement, equivalent road must be saturated and
               there exists path S~>w and u~>T in residual after maxflow. */
            if (saturated && fromS[u] && toT[w] && comp[u] != comp[w]) {
                cnt++;
            }
        }
    }

    if (cnt == 0) {
        printf("%d 0\n", F);
    } else {
        printf("%d %lld\n", F + 1, cnt);
    }

    return 0;
}

