#include <bits/stdc++.h>
using namespace std;

/*
We need the maximum number of edge-disjoint S->T paths in a directed graph,
after optionally reversing exactly one edge.

Let current max flow = F (unit capacities on edges).

A classic fact:
- After computing a max flow, build the residual graph.
- Let A = vertices reachable from S in residual.
- Let B = vertices from which T is reachable in residual
      (equivalently reachable from T in reverse residual).
Then for any non-existing residual augmenting path, A and B are disjoint.

Reversing one original edge e=(u,v):
This can increase max flow by at most 1.
It increases it iff in the residual graph there is a path S -> v and u -> T,
i.e. v in A and u in B. Intuition: after reversing (u,v) to (v,u), we add one
residual arc v->u, which may connect A to B and create an augmenting path.

However, if the reversed edge itself currently carries flow, then in residual
there is already arc v->u, so reversing it does not add anything new and cannot
increase the max flow. Thus we need:
  - original edge (u,v) has flow 0
  - v in A
  - u in B

Then new maximum is F+1.
Otherwise it stays F.

So:
1) Compute max flow with Dinic (unit capacities).
2) From residual graph, mark A = reachable from S.
3) Mark B = can reach T, by BFS/DFS from T on reverse residual.
4) Count original edges e=(u,v) with flow 0 and A[v] and B[u].
If count>0, answer: F+1 and count.
Else answer: F and M (reversing any edge keeps max), or perhaps count all roads
achieving the maximum. Since if no edge can improve, every road yields maximum F.
So answer count = M.

Need to verify statement asks "if so, calculate the new maximum number of trucks
and how many roads can be reversed to achieve this maximum."
This means among all single-edge reversals, find the maximum achievable flow and
the number of edges whose reversal attains that maximum.
Since gain is at most 1, if none improve, maximum is F and all M edges attain it.

Input format is not explicitly shown; common style:
N M S T
then M lines: a b
We implement that.
*/

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    int n;
    vector<vector<Edge>> g;
    vector<int> level, it;

    Dinic(int n): n(n), g(n), level(n), it(n) {}

    int addEdge(int fr, int to, int cap) {
        int idx = (int)g[fr].size();
        int ridx = (int)g[to].size();
        g[fr].push_back({to, ridx, cap});
        g[to].push_back({fr, idx, 0});
        return idx;
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); i++) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int maxflow(int s, int t) {
        int flow = 0, inf = 1e9;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (true) {
                int f = dfs(s, t, inf);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }
};

struct OrigEdge {
    int u, v;
    int idx; // index in g[u] of forward edge
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, S, T;
    if (!(cin >> N >> M >> S >> T)) return 0;
    --S; --T;

    Dinic dinic(N);
    vector<OrigEdge> edges;
    edges.reserve(M);

    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        int idx = dinic.addEdge(a, b, 1);
        edges.push_back({a, b, idx});
    }

    int F = dinic.maxflow(S, T);

    vector<int> A(N, 0), B(N, 0);

    // Reachable from S in residual graph
    {
        queue<int> q;
        q.push(S);
        A[S] = 1;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : dinic.g[v]) {
                if (e.cap > 0 && !A[e.to]) {
                    A[e.to] = 1;
                    q.push(e.to);
                }
            }
        }
    }

    // Vertices that can reach T in residual graph:
    // BFS from T on reverse residual graph
    {
        vector<vector<int>> revAdj(N);
        for (int u = 0; u < N; u++) {
            for (auto &e : dinic.g[u]) {
                if (e.cap > 0) {
                    revAdj[e.to].push_back(u);
                }
            }
        }
        queue<int> q;
        q.push(T);
        B[T] = 1;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int p : revAdj[v]) {
                if (!B[p]) {
                    B[p] = 1;
                    q.push(p);
                }
            }
        }
    }

    long long cntImprove = 0;
    for (auto &oe : edges) {
        auto &e = dinic.g[oe.u][oe.idx];
        // original edge cap was 1, so after max flow:
        // e.cap==1 <=> flow 0, e.cap==0 <=> flow 1
        bool flowZero = (e.cap == 1);
        if (flowZero && A[oe.v] && B[oe.u]) cntImprove++;
    }

    if (cntImprove > 0) {
        cout << (F + 1) << " " << cntImprove << "\n";
    } else {
        cout << F << " " << M << "\n";
    }

    return 0;
}

