                if (e.cap > 0 && level[v] < level[e.to]) {
                    int d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        graph[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
                it[v]++;
            }
            return 0;
        }
        int maxFlow(int s, int t) {
            int flow = 0;
            int INF = Integer.MAX_VALUE;
            while (true) {
                bfs(s);
                if (level[t] < 0) break;
                Arrays.fill(it, 0);
                int f;
                while ((f = dfs(s, t, INF)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
        // residual graph: edges with cap>0 go forward, reversed edges (cap>0 in original reverse) go backward
        boolean[] reachableFromS(int s) {
            boolean[] vis = new boolean[n];
            Queue<Integer> q = new LinkedList<>();
            vis[s] = true;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : graph[v]) {
                    if (e.cap > 0 && !vis[e.to]) {
                        vis[e.to] = true;
                        q.add(e.to);
                    }
                }
            }
            return vis;
        }
        boolean[] canReachT(int t) {
            // reverse graph traversal: edges that have capacity>0 in original direction from v->u means u can go to v in reverse
            boolean[] vis = new boolean[n];
            Queue<Integer> q = new LinkedList<>();
            vis[t] = true;
            q.add(t);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : graph[v]) {
                    // reversed edge: if original edge from e.to to v had cap>0, then v can reach e.to in reverse
                    // In our graph, the reverse edge is at index e.rev in graph[e.to].
                    Edge revEdge = graph[e.to].get(e.rev);
                    if (revEdge.cap > 0 && !vis[e.to]) {
                        vis[e.to] = true;
                        q.add(e.to);
                    }
                }
            }
            return vis;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int S = sc.nextInt() - 1;
        int T = sc.nextInt() - 1;
        int[][] edges = new int[M][2];
        for (int i = 0; i < M; i++) {
            edges[i][0] = sc.nextInt() - 1;
            edges[i][1] = sc.nextInt() - 1;
        }
        Dinic dinic = new Dinic(N);
        for (int[] e : edges) {
            dinic.addEdge(e[0], e[1], 1);
        }
        int originalFlow = dinic.maxFlow(S, T);

        boolean[] fromS = dinic.reachableFromS(S);
        boolean[] toT = dinic.canReachT(T);

        int count = 0;
        for (int i = 0; i < M; i++) {
            int u = edges[i][0], v = edges[i][1];
            // Check if reversing (u->v) increases flow
            // Condition: In residual, S can reach u and v can reach T
            if (fromS[u] && toT[v]) {
                count++;
            }
        }
        System.out.println((originalFlow + 1) + " " + count);
    }
