def max_flow_dinic(graph, source, sink, n):
    # graph[u] = list of [v, cap, rev_index]
    level = [0] * n
    iter_ = [0] * n

    def bfs(s):
        level[:] = [-1] * n
        queue = deque()
        level[s] = 0
        queue.append(s)
        while queue:
            v = queue.popleft()
            for e in graph[v]:
                if e[1] > 0 and level[e[0]] < 0:
                    level[e[0]] = level[v] + 1
                    queue.append(e[0])

    def dfs(v, t, f):
        if v == t:
            return f
        while iter_[v] < len(graph[v]):
            e = graph[v][iter_[v]]
            if e[1] > 0 and level[v] < level[e[0]]:
                d = dfs(e[0], t, min(f, e[1]))
                if d > 0:
                    e[1] -= d
                    graph[e[0]][e[2]][1] += d
                    return d
            iter_[v] += 1
        return 0

    flow = 0
    while True:
        bfs(source)
        if level[sink] < 0:
            return flow
        iter_[:] = [0] * n
        while True:
            f = dfs(source, sink, float('inf'))
            if f == 0:
                break
            flow += f

def build_and_flow(edges, n, s, t, skip_idx, add_edge=None):
    graph = [[] for _ in range(n)]
    for i, (u, v) in enumerate(edges):
        if i == skip_idx:
            continue
        # forward edge
        graph[u].append([v, 1, len(graph[v])])
        graph[v].append([u, 0, len(graph[u])-1])
    if add_edge:
        u, v = add_edge
        graph[u].append([v, 1, len(graph[v])])
        graph[v].append([u, 0, len(graph[u])-1])
    return max_flow_dinic(graph, s, t, n)

