    edges = []
    dinic = Dinic(N)
    for _ in range(M):
        u, v = map(int, input().split())
        dinic.add_edge(u, v, 1)
        edges.append((u, v))

    original_flow = dinic.max_flow(S, T)

    # Find reachable from S in residual graph
    visited = [False] * N
    q = deque([S])
    visited[S] = True
    while q:
        u = q.popleft()
        for v, cap, rev in dinic.graph[u]:
            if cap > 0 and not visited[v]:
                visited[v] = True
                q.append(v)

    # Find min cut edges (original direction from visited to not visited, saturated)
    cut_edges = []
    for idx, (u, v) in enumerate(edges):
        if visited[u] and not visited[v]:
            cut_edges.append(idx)

    best_flow = original_flow
    count = 0

    for idx in cut_edges:
        u, v = edges[idx]
        # Build new graph with this edge reversed
        dinic2 = Dinic(N)
        for j, (a, b) in enumerate(edges):
